head.script:
// 파일 관리 컴포넌트 전역 변수
scwin.fileConfig = {
    entityId: "",
    entityType: "default",
    maxFileCount: 10,
    maxFileSize: 10485760, // 10MB
    apiUrls: {
        fileList: "/InsWebApp/FileList.pwkjson",
        fileDelete: "/InsWebApp/FileDelete.pwkjson",
        fileDownload: "/InsWebApp/FileDownload.pwkjson",
        filePreview: "/InsWebApp/FilePreview.pwkjson",
        imagePreview: "/InsWebApp/ImagePreview.pwkjson"
    }
};

/**
 * 파일 관리자 초기화 (엔티티별 API 설정)
 */
scwin.initFileManager = function(config) {
    console.log("파일 관리자 초기화:", config);

    if (config) {
        scwin.fileConfig = Object.assign(scwin.fileConfig, config);
    }

    // 데이터 초기화
    scwin.clearFiles();

    // ⭐ 엔티티별 데이터맵 설정
    dmp_fileConfig.set("entityId", scwin.fileConfig.entityId || "");
    dmp_fileConfig.set("entityType", scwin.fileConfig.entityType || "default");
    dmp_fileConfig.set("maxFileCount", scwin.fileConfig.maxFileCount || 10);
    dmp_fileConfig.set("maxFileSize", scwin.fileConfig.maxFileSize || 10485760);

    // ⭐ API URL 설정 (기존 submission 체크 제거)
    if (scwin.fileConfig.apiUrls && scwin.fileConfig.apiUrls.fileList) {
        dmp_fileConfig.set("apiFileList", scwin.fileConfig.apiUrls.fileList);
        console.log("파일 목록 API 설정:", scwin.fileConfig.apiUrls.fileList);
    }

    if (scwin.fileConfig.apiUrls && scwin.fileConfig.apiUrls.fileDelete) {
        dmp_fileConfig.set("apiFileDelete", scwin.fileConfig.apiUrls.fileDelete);
        console.log("파일 삭제 API 설정:", scwin.fileConfig.apiUrls.fileDelete);
    }

    // ⭐ 엔티티 타입별 데이터 구조 설정
    scwin.setEntityDataStructure(scwin.fileConfig.entityType);

    console.log("파일 관리자 초기화 완료");
};
// 파일 업로드 관련 함수들 (UnitTestPopup 스타일)
scwin.multiUploadSelectDone = function() {
    console.log("=== 파일 선택 완료 콜백 실행 ===");

    var fileInfos = mpd_html5Type.getFileInfos();
    console.log("getFileInfos() 결과:", fileInfos);

    var newFileData = [];

    if (fileInfos && fileInfos.length > 0) {
        for (var i = 0; i < fileInfos.length; i++) {
            var file = fileInfos[i];

            newFileData.push({
                originalFileName: file.name,
                fileSize: scwin.formatFileSize(file.size),
                fileExtension: scwin.getFileExtension(file.name),
                status: "업로드 대기"
            });
        }
    }

    dlt_upload.setJSON(newFileData);

    try {
        grd_uploadList.refresh();
    } catch(e) {
        console.log("그리드 새로고침 실패, 무시");
    }

    console.log("업로드 대기 파일 수:", newFileData.length);
};

scwin.getFileExtension = function(fileName) {
    if (!fileName || fileName.indexOf('.') === -1) return '';
    return fileName.split('.').pop().toLowerCase();
};

scwin.btn_InitMultiupload_onclick = function(e) {
    console.log("파일 업로드 초기화");

    dlt_upload.setJSON([]);

    if (mpd_html5Type) {
        if (mpd_html5Type.clear) {
            mpd_html5Type.clear();
        } else if (mpd_html5Type.removeAllFiles) {
            mpd_html5Type.removeAllFiles();
        } else if (mpd_html5Type.fileArray) {
            mpd_html5Type.fileArray = [];
        }
    }

    console.log("파일 업로드 초기화 완료");
};

scwin.removeUploadFile = function(row, col, colId, targetId) {
    console.log("업로드 파일 삭제:", row);

    try {
        dlt_upload.removeRow(row);

        if (mpd_html5Type && mpd_html5Type.removeFileByIndex) {
            mpd_html5Type.removeFileByIndex(row);
        } else if (mpd_html5Type && mpd_html5Type.fileArray) {
            mpd_html5Type.fileArray.splice(row, 1);
        }

        try {
            grd_uploadList.refresh();
        } catch(e) {
            console.log("그리드 새로고침 실패, 무시");
        }

    } catch(error) {
        console.error("파일 삭제 중 오류:", error);
        alert("파일 삭제 중 오류가 발생했습니다.");
    }
};

scwin.mpd_html5Type_ondone = function(e) {
    console.log("파일 업로드 완료:", e);
    // 업로드 완료 후 파일 목록 새로고침
    var entityId = dmp_fileConfig.get("entityId");
    var entityType = dmp_fileConfig.get("entityType");
    if (entityId) {
        scwin.loadFileList(entityId, entityType);
    }
};

/**
 * 엔티티 타입별 데이터 구조 설정
 */
scwin.setEntityDataStructure = function(entityType) {
    console.log("엔티티 타입별 데이터 구조 설정:", entityType);

    switch (entityType) {
        case "DEFECT":
            // 결함용: id 필드 사용
            dmp_fileConfig.set("refType", "DEFECT");
            dmp_fileConfig.set("refId", scwin.fileConfig.entityId);
            console.log("결함용 데이터 구조 설정");
            break;

        case "UNIT_TEST":
            // 단위테스트용: testCaseId 필드 사용
            dmp_fileConfig.set("refType", "UNIT_TEST");
            dmp_fileConfig.set("refId", scwin.fileConfig.entityId);
            console.log("단위테스트용 데이터 구조 설정");
            break;

        default:
            // 기본 구조
            dmp_fileConfig.set("refType", entityType || "default");
            dmp_fileConfig.set("refId", scwin.fileConfig.entityId);
            console.log("기본 데이터 구조 설정");
            break;
    }
};

/**
 * 파일 설정 업데이트 (동적 API 지원)
 */
scwin.setFileConfig = function(config) {
    if (config) {
        scwin.fileConfig = Object.assign(scwin.fileConfig, config);

        // ⭐ API URL 동적 변경
        if (config.apiUrls) {
            scwin.setApiUrls(config.apiUrls);
        }

        // 데이터맵 업데이트
        dmp_fileConfig.set("entityId", config.entityId || dmp_fileConfig.get("entityId"));
        dmp_fileConfig.set("entityType", config.entityType || dmp_fileConfig.get("entityType"));
        dmp_fileConfig.set("maxFileCount", config.maxFileCount || dmp_fileConfig.get("maxFileCount"));
        dmp_fileConfig.set("maxFileSize", config.maxFileSize || dmp_fileConfig.get("maxFileSize"));

        // 엔티티별 데이터 구조 재설정
        if (config.entityType) {
            scwin.setEntityDataStructure(config.entityType);
        }

        console.log("FileManager 설정 업데이트 완료:", scwin.fileConfig);
    }
};

/**
 * API URL 동적 변경 함수
 */
scwin.setApiUrls = function(urls) {
    console.log("API URL 동적 설정:", urls);

    try {
        if (urls.fileList) {
            dmp_fileConfig.set("apiFileList", urls.fileList);
            console.log("파일 목록 API URL 설정:", urls.fileList);
        }

        if (urls.fileDelete) {
            dmp_fileConfig.set("apiFileDelete", urls.fileDelete);
            console.log("파일 삭제 API URL 설정:", urls.fileDelete);
        }

        // 기타 URL들도 저장
        if (urls.fileDownload) {
            scwin.fileConfig.apiUrls.fileDownload = urls.fileDownload;
        }
        if (urls.filePreview) {
            scwin.fileConfig.apiUrls.filePreview = urls.filePreview;
        }
        if (urls.imagePreview) {
            scwin.fileConfig.apiUrls.imagePreview = urls.imagePreview;
        }

    } catch (e) {
        console.error("API URL 설정 실패:", e);
    }
};

/**
 * submission 실행 전 데이터 구조 확인
 */
scwin.sbm_selectFileList_submit = function(e) {
    console.log("=== submission 기반 파일 목록 조회는 사용하지 않음 ===");
    console.log("직접 API 호출 방식을 사용합니다.");

    // 이 함수는 더 이상 사용하지 않음
    return false;
};


/**
 * 결함 파일 목록 직접 로드
 */
scwin.loadDefectFileListDirectly = function(defectId) {
    console.log("=== 결함 파일 목록 직접 로드 ===", defectId);

    try {
        var requestData = {
            defVo: {
                id: defectId
            }
        };

        console.log("결함 파일 목록 API 요청:", requestData);

        fetch("/InsWebApp/DEF001FileList.pwkjson", {
            method: "POST",
            headers: {
                "Content-Type": "application/json"
            },
            body: JSON.stringify(requestData)
        })
        .then(function(response) { 
            console.log("API 응답 상태:", response.status);
            return response.json(); 
        })
        .then(function(data) {
            console.log("결함 파일 목록 조회 응답:", data);
            scwin.handleFileListResponse(data);
        })
        .catch(function(error) {
            console.error("결함 파일 목록 조회 오류:", error);
            scwin.handleFileListError(error);
        });

    } catch (e) {
        console.error("결함 파일 목록 직접 로드 실패:", e);
        scwin.handleFileListError(e);
    }
};
/**
 * 단위테스트 파일 목록 직접 로드
 */
scwin.loadUnitTestFileListDirectly = function(testCaseId) {
    console.log("=== 단위테스트 파일 목록 직접 로드 ===", testCaseId);

    try {
        var requestData = {
            unitTestVo: {
                testCaseId: testCaseId
            }
        };

        console.log("단위테스트 파일 목록 API 요청:", requestData);

        fetch("/InsWebApp/UNIT001FileList.pwkjson", {
            method: "POST",
            headers: {
                "Content-Type": "application/json"
            },
            body: JSON.stringify(requestData)
        })
        .then(function(response) { 
            console.log("API 응답 상태:", response.status);
            return response.json(); 
        })
        .then(function(data) {
            console.log("단위테스트 파일 목록 조회 응답:", data);
            scwin.handleFileListResponse(data);
        })
        .catch(function(error) {
            console.error("단위테스트 파일 목록 조회 오류:", error);
            scwin.handleFileListError(error);
        });

    } catch (e) {
        console.error("단위테스트 파일 목록 직접 로드 실패:", e);
        scwin.handleFileListError(e);
    }
};

/**
 * 파일 목록 응답 처리 (공통)
 */
scwin.handleFileListResponse = function(data) {
    try {
        if (data.elHeader && data.elHeader.resSuc) {
            var fileList = data.elData ? data.elData.attVoList : [];
            console.log("조회된 파일 목록:", fileList);

            // 파일 크기 포맷팅 적용
            if (fileList && fileList.length > 0) {
                for (var i = 0; i < fileList.length; i++) {
                    var file = fileList[i];
                    if (file.fileSize && !isNaN(file.fileSize)) {
                        file.fileSizeFormatted = scwin.formatFileSize(parseInt(file.fileSize));
                    } else {
                        file.fileSizeFormatted = file.fileSize || "알 수 없음";
                    }
                }
            }

            dlt_attVoList.setJSON(fileList || []);

            if (!fileList || fileList.length === 0) {
                scwin.hideAllPreviewPanels();
                scwin.showNoPreview();
                console.log("첨부된 파일이 없습니다.");
            } else {
                console.log("파일 목록 표시 완료:", fileList.length, "개");
            }
        } else {
            var errorMsg = data.elHeader ? data.elHeader.resMsg : "알 수 없는 오류";
            console.error("파일 목록 조회 실패:", errorMsg);
            scwin.handleFileListError(new Error(errorMsg));
        }
    } catch (e) {
        console.error("파일 목록 응답 처리 실패:", e);
        scwin.handleFileListError(e);
    }
};

/**
 * 파일 목록 오류 처리 (공통)
 */
scwin.handleFileListError = function(error) {
    console.error("파일 목록 오류:", error);

    dlt_attVoList.setJSON([]);
    scwin.hideAllPreviewPanels();
    scwin.showNoPreview();

    // 에러 메시지 표시 (선택사항)
    console.log("파일 목록을 불러올 수 없습니다:", error.message);
};
/**
 * 파일 목록 로드
 */
/**
 * 파일 목록 로드 (submission 방식)
 */
scwin.loadFileList = function(entityId, entityType) {
    console.log("=== 파일 목록 로드 시작 ===", entityId, entityType);

    if (entityId) {
        dmp_fileConfig.set("entityId", entityId);
        scwin.fileConfig.entityId = entityId;
    }
    if (entityType) {
        dmp_fileConfig.set("entityType", entityType);
        scwin.fileConfig.entityType = entityType;

        // 엔티티별 데이터 구조 재설정
        scwin.setEntityDataStructure(entityType);
    }

    var currentEntityId = dmp_fileConfig.get("entityId");

    if (!currentEntityId || currentEntityId.trim() === "") {
        console.log("엔티티 ID가 없습니다. 파일 목록을 초기화합니다.");
        dlt_attVoList.setJSON([]);
        scwin.hideAllPreviewPanels();
        scwin.showNoPreview();
        return;
    }

    console.log("파일 목록 조회 요청 - entityId:", currentEntityId, "entityType:", entityType);

    try {
        // ⭐ 엔티티 타입별로 다른 submission 사용
        if (entityType === "DEFECT") {
            // 결함: dmp_fileConfig에 id 값 설정
            dmp_fileConfig.set("id", currentEntityId);

            console.log("결함용 submission 실행");
            $c.sbm.execute($p, sbm_selectDefFileList);

        } else if (entityType === "UNIT_TEST") {
            // 단위테스트: dmp_fileConfig에 testCaseId 값 설정
            dmp_fileConfig.set("testCaseId", currentEntityId);

            console.log("단위테스트용 submission 실행");
            $c.sbm.execute($p, sbm_selectUnitFileList);

        } else {
            console.warn("지원하지 않는 엔티티 타입:", entityType);
            scwin.handleFileListError(new Error("지원하지 않는 엔티티 타입: " + entityType));
        }

    } catch (e) {
        console.error("파일 목록 로드 실패:", e);
        scwin.handleFileListError(e);
    }
};

/**
 * 결함 파일 목록 조회 완료
 */
scwin.sbm_selectDefFileList_submitdone = function(e) {
    console.log("=== 결함 파일 목록 조회 응답 처리 시작 ===");
    console.log("전체 응답:", e);

    try {
        var responseData = e.responseJSON;
        var elData = responseData ? responseData.elData : null;
        var elHeader = responseData ? responseData.elHeader : null;

        console.log("응답 헤더:", elHeader);
        console.log("응답 데이터:", elData);

        if (!elHeader || elHeader.resSuc !== true) {
            var errorMsg = "파일 목록 조회에 실패했습니다.";
            if (elHeader && elHeader.resMsg) {
                errorMsg += "\n오류메시지: " + elHeader.resMsg;
            }
            console.error("조회 실패:", errorMsg);
            scwin.handleFileListError(new Error(errorMsg));
            return;
        }

        var fileList = [];
        if (elData && elData.attVoList) {
            fileList = elData.attVoList;
            console.log("파일 목록 데이터:", fileList);

            // 파일 크기 포맷팅 적용
            for (var i = 0; i < fileList.length; i++) {
                var file = fileList[i];
                if (file.fileSize && !isNaN(file.fileSize)) {
                    file.fileSizeFormatted = scwin.formatFileSize(parseInt(file.fileSize));
                } else {
                    file.fileSizeFormatted = file.fileSize || "알 수 없음";
                }
            }
        }

        console.log("그리드에 설정할 파일 개수:", fileList.length);
        dlt_attVoList.setJSON(fileList);

        if (fileList.length === 0) {
            scwin.hideAllPreviewPanels();
            scwin.showNoPreview();
            console.log("첨부된 파일이 없습니다.");
        } else {
            console.log("파일 목록 표시 완료:", fileList.length, "개");
        }

        console.log("=== 결함 파일 목록 조회 응답 처리 완료 ===");

    } catch (error) {
        console.error("응답 처리 중 오류:", error);
        scwin.handleFileListError(error);
    }
};

/**
 * 단위테스트 파일 목록 조회 완료
 */
scwin.sbm_selectUnitFileList_submitdone = function(e) {
    console.log("=== 단위테스트 파일 목록 조회 응답 처리 시작 ===");
    // 결함과 동일한 처리 로직
    scwin.sbm_selectDefFileList_submitdone(e);
};

/**
 * 결함 파일 목록 조회 실패
 */
scwin.sbm_selectDefFileList_submiterror = function(e) {
    console.error("결함 파일 목록 조회 실패:", e);
    console.error("실패 상세:", e.statusText, e.responseText);
    scwin.handleFileListError(new Error("결함 파일 목록 조회 실패: " + e.statusText));
};

/**
 * 단위테스트 파일 목록 조회 실패
 */
scwin.sbm_selectUnitFileList_submiterror = function(e) {
    console.error("단위테스트 파일 목록 조회 실패:", e);
    console.error("실패 상세:", e.statusText, e.responseText);
    scwin.handleFileListError(new Error("단위테스트 파일 목록 조회 실패: " + e.statusText));
};

/**
 * 파일 목록 오류 처리 (공통)
 */
scwin.handleFileListError = function(error) {
    console.error("파일 목록 오류:", error);

    dlt_attVoList.setJSON([]);
    scwin.hideAllPreviewPanels();
    scwin.showNoPreview();

    // 에러 메시지 표시 (선택사항)
    console.log("파일 목록을 불러올 수 없습니다:", error.message);
};


/**
 * 직접 API 호출로 파일 목록 로드 (submission 실패 시 대안)
 */
scwin.loadFileListDirectly = function(entityId, entityType) {
    console.log("=== 직접 API 호출로 파일 목록 로드 ===", entityId, entityType);

    try {
        var apiUrl = "/InsWebApp/FileList.pwkjson";

        // 엔티티 타입별 API URL 설정
        if (entityType === "DEFECT") {
            apiUrl = "/InsWebApp/DEF001FileList.pwkjson";
        } else if (entityType === "UNIT_TEST") {
            apiUrl = "/InsWebApp/UNIT001FileList.pwkjson";
        }

        var requestData = {};

        // 엔티티 타입별 데이터 구조
        if (entityType === "DEFECT") {
            requestData.defVo = { id: entityId };
        } else if (entityType === "UNIT_TEST") {
            requestData.unitTestVo = { testCaseId: entityId };
        } else {
            requestData.fileSearchVo = { 
                refType: entityType,
                refId: entityId 
            };
        }

        console.log("직접 API 호출:", apiUrl, requestData);

        fetch(apiUrl, {
            method: "POST",
            headers: {
                "Content-Type": "application/json"
            },
            body: JSON.stringify(requestData)
        })
        .then(function(response) { 
            console.log("API 응답 상태:", response.status);
            return response.json(); 
        })
        .then(function(data) {
            console.log("파일 목록 조회 응답:", data);

            if (data.elHeader && data.elHeader.resSuc) {
                var fileList = data.elData ? data.elData.attVoList : [];
                console.log("조회된 파일 목록:", fileList);

                // 파일 크기 포맷팅 적용
                if (fileList && fileList.length > 0) {
                    for (var i = 0; i < fileList.length; i++) {
                        var file = fileList[i];
                        if (file.fileSize && !isNaN(file.fileSize)) {
                            file.fileSizeFormatted = scwin.formatFileSize(parseInt(file.fileSize));
                        } else {
                            file.fileSizeFormatted = file.fileSize || "알 수 없음";
                        }
                    }
                }

                dlt_attVoList.setJSON(fileList || []);

                if (!fileList || fileList.length === 0) {
                    scwin.hideAllPreviewPanels();
                    scwin.showNoPreview();
                    console.log("첨부된 파일이 없습니다.");
                } else {
                    console.log("파일 목록 표시 완료:", fileList.length, "개");
                }
            } else {
                var errorMsg = data.elHeader ? data.elHeader.resMsg : "알 수 없는 오류";
                console.error("파일 목록 조회 실패:", errorMsg);
                dlt_attVoList.setJSON([]);
            }
        })
        .catch(function(error) {
            console.error("파일 목록 조회 오류:", error);
            dlt_attVoList.setJSON([]);
        });

    } catch (e) {
        console.error("직접 API 호출 실패:", e);
        dlt_attVoList.setJSON([]);
    }
};

/**
 * 파일 목록 조회 완료
 */
scwin.sbm_selectFileList_submitdone = function(e) {
    console.log("=== 파일 목록 조회 응답 처리 시작 ===");
    console.log("전체 응답:", e);

    try {
        var responseData = e.responseJSON;
        var elData = responseData ? responseData.elData : null;
        var elHeader = responseData ? responseData.elHeader : null;

        console.log("응답 헤더:", elHeader);
        console.log("응답 데이터:", elData);

        if (!elHeader || elHeader.resSuc !== true) {
            var errorMsg = "파일 목록 조회에 실패했습니다.";
            if (elHeader && elHeader.resMsg) {
                errorMsg += "\n오류메시지: " + elHeader.resMsg;
            }
            if (elHeader && elHeader.resCode) {
                errorMsg += "\n오류코드: " + elHeader.resCode;
            }
            console.error("조회 실패:", errorMsg);

            dlt_attVoList.setJSON([]);
            return;
        }

        var fileList = [];
        if (elData && elData.attVoList) {
            fileList = elData.attVoList;
            console.log("파일 목록 데이터:", fileList);

            // 파일 크기 포맷팅 적용
            for (var i = 0; i < fileList.length; i++) {
                var file = fileList[i];

                if (file.fileSize && !isNaN(file.fileSize)) {
                    file.fileSizeFormatted = scwin.formatFileSize(parseInt(file.fileSize));
                } else {
                    file.fileSizeFormatted = file.fileSize || "알 수 없음";
                }
            }
        }

        console.log("그리드에 설정할 파일 개수:", fileList.length);
        dlt_attVoList.setJSON(fileList);

        if (fileList.length === 0) {
            scwin.hideAllPreviewPanels();
            scwin.showNoPreview();
            console.log("첨부된 파일이 없습니다.");
        } else {
            console.log("파일 목록 표시 완료:", fileList.length, "개");
        }

        console.log("=== 파일 목록 조회 응답 처리 완료 ===");

    } catch (error) {
        console.error("응답 처리 중 오류:", error);
        dlt_attVoList.setJSON([]);
    }
};

// ===== 기존 함수들 유지 =====
scwin.clearFiles = function() {
    try {
        dlt_attVoList.setJSON([]);
        dmp_currentFile.setEmptyValue();

        if (typeof mpd_html5Type !== 'undefined' && mpd_html5Type) {
            if (mpd_html5Type.clear) {
                mpd_html5Type.clear();
            }
        }

        scwin.hideAllPreviewPanels();
        scwin.showNoPreview();

        console.log("파일 관련 데이터 초기화 완료");
    } catch (e) {
        console.error("파일 데이터 초기화 실패:", e);
    }
};

scwin.formatFileSize = function(bytes) {
    if (bytes === 0 || !bytes) return '0 B';

    var k = 1024;
    var sizes = ['B', 'KB', 'MB', 'GB', 'TB'];
    var i = Math.floor(Math.log(bytes) / Math.log(k));

    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
};

scwin.hideAllPreviewPanels = function() {
    try {
        grp_noPreview.hide();
        grp_imagePreview.hide();
        // grp_textPreview는 더 이상 사용 안 함
        if (typeof grp_textPreview !== 'undefined') {
            grp_textPreview.hide();
        }
        grp_documentPreview.hide();
    } catch(e) {
        console.error("미리보기 패널 숨기기 오류:", e);
    }
};

/**
 * 현재 파일 다운로드 (미리보기에서 호출)
 */
scwin.downloadCurrentFile = function() {
    var fileId = dmp_currentFile.get("fileId");
    var fileName = dmp_currentFile.get("originalFileName");

    console.log("현재 파일 다운로드:", fileId, fileName);

    if (fileId && fileName) {
        scwin.downloadFile(fileId, fileName);
    } else {
        alert("다운로드할 파일 정보가 없습니다.");
    }
};

scwin.showNoPreview = function() {
    try {
        grp_noPreview.show();
    } catch(e) {
        console.error("기본 미리보기 표시 오류:", e);
    }
};

scwin.sbm_selectFileList_submiterror = function(e) {
    console.error("파일 목록 조회 실패:", e);
    console.error("실패 상세:", e.statusText, e.responseText);

    dlt_attVoList.setJSON([]);
    scwin.hideAllPreviewPanels();
    scwin.showNoPreview();
};

// ===== 파일 다운로드 및 삭제 기능 =====
scwin.downloadFile = function(fileId, fileName) {
    console.log("파일 다운로드:", fileName, "ID:", fileId);

    if (!fileId || !fileName) {
        alert("다운로드할 파일 정보가 없습니다.");
        return;
    }

    try {
        var downloadUrl = scwin.fileConfig.apiUrls.fileDownload + "?fileId=" + encodeURIComponent(fileId);

        var iframe = document.createElement('iframe');
        iframe.style.display = 'none';
        iframe.src = downloadUrl;
        document.body.appendChild(iframe);

        setTimeout(function() {
            if (iframe.parentNode) {
                document.body.removeChild(iframe);
            }
        }, 3000);

        console.log("파일 다운로드 요청 완료");

    } catch (error) {
        console.error("파일 다운로드 실패:", error);
        alert("파일 다운로드 중 오류가 발생했습니다: " + error.message);
    }
};

scwin.deleteFile = function(fileId) {
    console.log("파일 삭제:", fileId);

    if (!fileId) {
        alert("삭제할 파일을 선택해주세요.");
        return;
    }

    var promise = $c.win.confirm("파일을 삭제하시겠습니까?");
    promise.then(function(result) {
        if (result) {
            dmp_currentFile.set("fileId", fileId);
            $c.sbm.execute($p, sbm_deleteFile);
        }
    });
};

scwin.sbm_deleteFile_submit = function(e) {
    var fileId = dmp_currentFile.get("fileId");
    if (!fileId) {
        console.error("삭제할 파일 ID가 없습니다.");
        return;
    }

    var deleteUrl = dmp_fileConfig.get("apiFileDelete") + "?fileId=" + encodeURIComponent(fileId);
    sbm_deleteFile.setAction(deleteUrl);
    sbm_deleteFile.setRequestData("");
};

scwin.sbm_deleteFile_submitdone = function(e) {
    console.log("파일 삭제 완료:", e);

    var elHeader = e.responseJSON.elHeader;

    if (!elHeader || elHeader.resSuc == false) {
        alert("파일 삭제 실패: " + (elHeader ? elHeader.resMsg : "알 수 없는 오류"));
        return;
    }

    alert("파일이 삭제되었습니다.");

    scwin.hideAllPreviewPanels();
    scwin.showNoPreview();
    dmp_currentFile.setEmptyValue();

    // 파일 목록 새로고침
    scwin.loadFileList();
};

// ===== 그리드 이벤트 핸들러 =====
scwin.grd_fileList_oncellclick = function(row, col, colId) {
    console.log("파일 그리드 셀 클릭:", row, colId);

    var rowData = dlt_attVoList.getRowJSON(row);

    if (colId === "originalFileName") {
        scwin.previewFile(rowData.fileId, rowData.originalFileName, rowData.fileExtension);
    }
};

scwin.fileActionClick = function(row, col, colId, targetId) {
    console.log("파일 액션 클릭:", row, targetId);

    var rowData = dlt_attVoList.getRowJSON(row);
    var fileId = rowData.fileId;
    var fileName = rowData.originalFileName;

    if (!fileId) {
        alert("파일 ID가 없습니다.");
        return;
    }

    if (targetId && (targetId.indexOf("download") >= 0 || targetId.indexOf("다운로드") >= 0)) {
        scwin.downloadFile(fileId, fileName);
    } else if (targetId && (targetId.indexOf("delete") >= 0 || targetId.indexOf("삭제") >= 0)) {
        scwin.deleteFile(fileId);
    } else {
        scwin.downloadFile(fileId, fileName);
    }
};

// ===== 미리보기 기능 (간소화) =====
scwin.previewFile = function(fileId, fileName, fileExtension) {
    console.log("=== 파일 미리보기 시작 ===");
    console.log("파일 ID:", fileId);
    console.log("파일명:", fileName);
    console.log("확장자:", fileExtension);

    if (!fileId || !fileName) {
        console.error("파일 정보가 부족합니다.");
        scwin.showNoPreview();
        return;
    }

    // 현재 파일 정보 저장
    dmp_currentFile.set("fileId", fileId);
    dmp_currentFile.set("originalFileName", fileName);
    dmp_currentFile.set("fileExtension", fileExtension);

    // 모든 미리보기 패널 숨기기
    scwin.hideAllPreviewPanels();

    try {
        // 확장자 정리
        var ext = fileExtension ? fileExtension.toLowerCase() : "";
        if (!ext && fileName) {
            var lastDot = fileName.lastIndexOf('.');
            if (lastDot > -1) {
                ext = fileName.substring(lastDot + 1).toLowerCase();
            }
        }

        console.log("처리된 확장자:", ext);

        // ⭐ 이미지 파일만 미리보기 지원
        if (scwin.isImageExtension(ext)) {
            console.log("이미지 파일 - 미리보기 표시");
            scwin.showImagePreview(fileId, fileName);
        } else {
            console.log("이미지가 아닌 파일 - 미리보기 불지원 메시지 표시");
            scwin.showUnsupportedPreview(fileName, ext);
        }

    } catch (e) {
        console.error("파일 미리보기 처리 실패:", e);
        scwin.showNoPreview();
    }
};

