/**
 * 미리보기 미지원 파일 표시
 */
scwin.showUnsupportedPreview = function(fileName, ext) {
    console.log("=== 미리보기 미지원 파일 표시 ===");
    console.log("파일명:", fileName);
    console.log("확장자:", ext);

    try {
        // 문서 미리보기 패널 사용 (메시지만 표시)
        grp_documentPreview.show();

        // 파일명 설정
        if (typeof txt_documentFileName !== 'undefined' && txt_documentFileName.setValue) {
            txt_documentFileName.setValue(fileName);
        }

        // ⭐ 미리보기 미지원 메시지
        var fileTypeMsg = scwin.getFileTypeDescription(ext);
        var message = "미리보기는 이미지만 지원합니다.\n" + fileTypeMsg + " 파일을 확인하려면 다운로드하세요.";

        if (typeof txt_documentInfo !== 'undefined' && txt_documentInfo.setValue) {
            txt_documentInfo.setValue(message);
        }

        console.log("미리보기 미지원 메시지 표시 완료");

    } catch (e) {
        console.error("미리보기 미지원 표시 실패:", e);
        scwin.showNoPreview();
    }
};

/**
 * 파일 타입 설명 반환 (간소화)
 */
scwin.getFileTypeDescription = function(ext) {
    switch (ext) {
        case "pdf": return "PDF 문서";
        case "doc":
        case "docx": return "Word 문서";
        case "xls":
        case "xlsx": return "Excel 문서";
        case "ppt":
        case "pptx": return "PowerPoint 문서";
        case "txt": return "텍스트";
        case "zip":
        case "rar":
        case "7z": return "압축";
        case "jpg":
        case "jpeg":
        case "png":
        case "gif":
        case "bmp":
        case "svg": return "이미지";
        default: return "일반";
    }
};

/**
 * 이미지 파일 확장자 체크
 */
scwin.isImageExtension = function(ext) {
    if (!ext) return false;
    var imageExts = ["jpg", "jpeg", "png", "gif", "bmp", "svg", "webp"];
    return imageExts.indexOf(ext.toLowerCase()) >= 0;
};

/**
 * 기본 미리보기 (파일 선택 안 함)
 */
scwin.showNoPreview = function() {
    try {
        grp_noPreview.show();
    } catch(e) {
        console.error("기본 미리보기 표시 오류:", e);
    }
};
